param([Parameter(Mandatory=$true)][string]$JobRoot,[string]$RepositoryRoot,[string]$AttemptId='oracle-v1')
$ErrorActionPreference='Stop';if(-not$RepositoryRoot){$RepositoryRoot=Join-Path $JobRoot 'repo'};$out=Join-Path $JobRoot "output\$AttemptId";if(Test-Path $out){throw 'exists'};New-Item -ItemType Directory -Path "$out\build"|Out-Null;$s=Join-Path $RepositoryRoot 'src\fg_dynamic_module23\rtx_oracle.cpp';$m=Join-Path $JobRoot 'inputs\cu-module-000023.bin';$cuda=if($env:CUDA_PATH){$env:CUDA_PATH}else{'C:\Program Files\NVIDIA GPU Computing Toolkit\CUDA\v13.3'};$vs=Join-Path ${env:ProgramFiles(x86)} 'Microsoft Visual Studio\Installer\vswhere.exe';$i=&$vs -latest -products '*' -requires Microsoft.VisualStudio.Component.VC.Tools.x86.x64 -property installationPath;$vc=Join-Path $i 'VC\Auxiliary\Build\vcvars64.bat';$exe="$out\build\p.exe";$obj="$out\build\p.obj";$log="$out\build\compile.log";$cmd='"{0}" >nul && cl /nologo /std:c++20 /EHsc /MD /W4 /WX /I"{1}" /Fo"{2}" /c "{3}" >"{4}" 2>&1 && link /nologo /OUT:"{5}" "{2}" "{6}" bcrypt.lib >>"{4}" 2>&1'-f$vc,(Join-Path $cuda 'include'),$obj,$s,$log,$exe,(Join-Path $cuda 'lib\x64\cuda.lib');&$env:ComSpec /d /s /c $cmd;if($LASTEXITCODE){throw 'compile'};$rs=@();foreach($r in @('720p','1080p','1440p','4k')){foreach($ph in @('reset','generated')){foreach($z in @('a5','5a')){foreach($q in @('a','b')){$id="$r-$ph-poison-$z-process-$q";$d=Join-Path $out $id;mkdir $d|Out-Null;$mode=if($z-eq'a5'-and$q-eq'a'){'full'}else{'hash-only'};$x=Start-Process $exe -ArgumentList @($m,$d,$id,$z,$r,$ph,$mode) -Wait -PassThru -NoNewWindow -RedirectStandardOutput "$d\stdout" -RedirectStandardError "$d\stderr";if($x.ExitCode){throw "run $id"};$v=gc "$d\run-receipt.json" -Raw|ConvertFrom-Json;if($v.result-ne'pass'){throw "receipt $id"};$rs+=$v}}}};$pids=@($rs.process_id|sort -Unique);if($pids.Count-ne32){throw 'pids'};$rec=[ordered]@{schema='neuralstudio.fg.dynamic-module23-rig.v1';job_id=Split-Path -Leaf $JobRoot;module_sha256=(Get-FileHash $m -Algorithm SHA256).Hash.ToLowerInvariant();source_sha256=(Get-FileHash $s -Algorithm SHA256).Hash.ToLowerInvariant();run_count=32;fresh_process_count=32;raw_buffer_abi=$true;selected_mode=0;expected_or_captured_output_ingress=$false;address_fields_recorded=$false;result='pass'};$u=New-Object Text.UTF8Encoding($false);$rp="$out\rig-receipt.json";[IO.File]::WriteAllText($rp,(($rec|ConvertTo-Json)+"`n"),$u);Write-Host "rig_receipt_sha256=$((Get-FileHash $rp -Algorithm SHA256).Hash.ToLowerInvariant())";Write-Host result=pass
